// Guards
import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

export const authGuard: CanActivateFn = (route, state) => {
  const auth = inject(AuthService);
  const router = inject(Router);

  if (auth.isLoggedIn()) return true;

  return router.parseUrl('/login?redirect=' + state.url);
};

// Custom preloading strategy
import { Observable } from 'rxjs';
import { PreloadingStrategy, Route } from '@angular/router';

export class SelectivePreloadStrategy implements PreloadingStrategy {
  preload(route: Route, load: () => Observable<any>): Observable<any> {
    return route.data?.['preload'] ? load() : of(null);
  }
}

Angular Forms & Validation:
// Reactive Forms with typed controls
import { Component, inject } from '@angular/core';
import { FormBuilder, Validators, FormArray, ReactiveFormsModule } from '@angular/forms';

interface UserForm {
  name: FormControl<string>;
  email: FormControl<string>;
  addresses: FormArray<FormGroup<AddressForm>>;
}

interface AddressForm {
  street: FormControl<string>;
  city: FormControl<string>;
  zip: FormControl<string>;
}

@Component({
  selector: 'app-user-form',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="userForm" (ngSubmit)="onSubmit()">
      <input formControlName="name" placeholder="Name" />
      @if (userForm.get('name')?.invalid && userForm.get('name')?.touched) {
        <span class="error">Name is required</span>
      }

      <input formControlName="email" placeholder="Email" />
      @if (userForm.get('email')?.hasError('email')) {
        <span class="error">Invalid email format</span>
      }

      <div formArrayName="addresses">
        @for (addr of addresses.controls; track i; let i = $index) {
          <div [formGroupName]="i">
            <input formControlName="street" placeholder="Street" />
            <input formControlName="city" placeholder="City" />
            <input formControlName="zip" placeholder="ZIP" />
          </div>
        }
        <button type="button" (click)="addAddress()">+ Add Address</button>
      </div>

      <button type="submit" [disabled]="userForm.invalid">Save</button>
    </form>
  `
})
export class UserFormComponent {
  private fb = inject(FormBuilder);

  userForm = this.fb.nonNullable.group<UserForm>({
    name: ['', [Validators.required, Validators.minLength(2)]],
    email: ['', [Validators.required, Validators.email]],
    addresses: this.fb.array<FormGroup<AddressForm>>([])
  });

  get addresses() { return this.userForm.get('addresses') as FormArray; }

  addAddress() {
    this.addresses.push(this.fb.nonNullable.group<AddressForm>({
      street: ['', Validators.required],
      city: ['', Validators.required],
      zip: ['', [Validators.required, Validators.pattern(/^\d{5}$/)]]
    }));
  }

  onSubmit() {
    if (this.userForm.valid) {
      console.log('Form submitted:', this.userForm.getRawValue());
    }
  }
}

