@Component({
  selector: 'app-heavy',
  template: `
    <h1>Main content (loaded immediately)</h1>

    <!-- Defer expensive component until visible -->
    @defer (on viewport) {
      <app-expensive-chart />
    } @placeholder {
      <div class="chart-placeholder">Chart loading...</div>
    } @loading (minimum 500ms) {
      <app-spinner />
    } @error {
      Failed to load chart

    }

    <!-- Defer until interaction -->
    @defer (on interaction) {
      <app-comment-section />
    } @placeholder {
      <button>Load comments</button>
    }

    <!-- Defer with conditions -->
    @defer (when isVisible()) {
      <app-data-table [data]="tableData()" />
    }
  `
})
export class DashboardComponent {
  isVisible = signal(false);
  tableData = signal<DataRow[]>([]);

  constructor() {
    // Load table data eagerly, but render deferred
    this.loadData();
  }
}

// Performance monitoring
@Component({
  selector: 'app-root',
  template: '...',
  host: {
    '[class.lcp-loaded]': 'lcpLoaded()'
  }
})
export class AppComponent {
  private perf = inject(PerformanceService);
  lcpLoaded = signal(false);

  constructor() {
    new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (entry.entryType === 'largest-contentful-paint') {
          this.lcpLoaded.set(true);
          console.log('LCP:', entry.startTime);
        }
      }
    }).observe({ type: 'largest-contentful-paint', buffered: true });
  }
}
